import {CLOUD} from './config.js';
const SESSION_KEY='ofek-session-v1';
export let session=JSON.parse(sessionStorage.getItem(SESSION_KEY)||'null');
export function setSession(value){session=value;if(value)sessionStorage.setItem(SESSION_KEY,JSON.stringify(value));else sessionStorage.removeItem(SESSION_KEY)}
export async function login(email,password){const r=await fetch(`${CLOUD.url}/auth/v1/token?grant_type=password`,{method:'POST',headers:{apikey:CLOUD.anonKey,'Content-Type':'application/json'},body:JSON.stringify({email,password})});const d=await r.json();if(!r.ok)throw new Error('פרטי הכניסה לא התקבלו. בדקו כתובת וסיסמה.');setSession({...d,expires_at:Math.floor(Date.now()/1000)+d.expires_in});return d}
async function token(){if(!session)throw new Error('נדרשת כניסה');if(session.expires_at<Date.now()/1000+90){const r=await fetch(`${CLOUD.url}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:CLOUD.anonKey,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});if(!r.ok){setSession(null);throw new Error('הכניסה פגה. יש להתחבר מחדש.')}const d=await r.json();setSession({...d,expires_at:Math.floor(Date.now()/1000)+d.expires_in})}return session.access_token}
export async function cloudRequest(method,body){const jwt=await token();const r=await fetch(`${CLOUD.url}/functions/v1/ofek-demo`,{method,headers:{apikey:CLOUD.anonKey,Authorization:`Bearer ${jwt}`,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw new Error(d.error||'לא ניתן לשמור בענן כרגע');return d}
export async function logout(){try{if(session)await fetch(`${CLOUD.url}/auth/v1/logout`,{method:'POST',headers:{apikey:CLOUD.anonKey,Authorization:`Bearer ${session.access_token}`}})}finally{setSession(null)}}
